import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadKeotiData(){const e=readFileSync(resolve(__dirname,"../../keoti-falls-explorer/keoti-data.js"),"utf-8");return new Function(e+"\nreturn { KEOTI_INFO, HEIGHT_COMPARISONS, SEASONAL_DATA, NEARBY_ATTRACTIONS, GALLERY_IMAGES, REFERENCES };")()}describe("Keoti Falls Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadKeotiData()}),describe("KEOTI_INFO metadata",()=>{it("contains correct Keoti Falls location and height attributes",()=>{expect(e.KEOTI_INFO.id).toBe("keoti-falls"),expect(e.KEOTI_INFO.title).toContain("Keoti Falls"),expect(e.KEOTI_INFO.height).toContain("98 Meters"),expect(e.KEOTI_INFO.waterSource).toContain("Mahana River")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.KEOTI_INFO.quickStats)).toBe(!0),expect(e.KEOTI_INFO.quickStats.length).toBe(6)})}),describe("HEIGHT_COMPARISONS & SEASONAL_DATA",()=>{it("contains height comparisons and seasonal flow data",()=>{expect(Array.isArray(e.HEIGHT_COMPARISONS)).toBe(!0),expect(e.HEIGHT_COMPARISONS.length).toBeGreaterThanOrEqual(4);const t=e.HEIGHT_COMPARISONS.find(e=>"Keoti Falls"===e.name);expect(t).toBeDefined(),expect(t.heightMeters).toBe(98),expect(Array.isArray(e.SEASONAL_DATA)).toBe(!0),expect(e.SEASONAL_DATA.length).toBeGreaterThanOrEqual(3)})}),describe("NEARBY_ATTRACTIONS & REFERENCES",()=>{it("contains nearby circuit attractions and references",()=>{expect(Array.isArray(e.NEARBY_ATTRACTIONS)).toBe(!0),expect(e.NEARBY_ATTRACTIONS.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});